function ParseNestedParens(parenString: string): array of integer;
{
  var maxlevel := 0;
  var levels := new List<integer>;
  var openlevel := 0;
  var (s,res) := (parenString.ToCharArray,new integer[parenString.Length]);
  for var i := 0 to s.Length - 1 do
  begin
    if s[i] = '(' then
      openlevel += 1
    else
    begin
      if openlevel = 0 then
        res[i] := 0
      else
      begin
        var level := 0;
        while (openlevel > 0) and (s[i - level - 1] <> '(') do
        begin
          openlevel -= 1;
          level += 1;
        end;
        if openlevel > 0 then
          s[i - level] := ')';
        if level > maxlevel then
          maxlevel := level;
        openlevel -= 1;
        res[i] := level + 1;
      end;
    end;
  end;
  if maxlevel > 0 then
  begin
    for var i := 0 to s.Length - 1 do
      if s[i] = '(' then
        s[i] := ')';
    var max := 0;
    var level := 0;
    for var i := 0 to s.Length - 1 do
    begin
      if s[i] = '(' then
      begin
        level += 1;
        if level = maxlevel then
          max += 1;
      end
      else
      begin
        if s[i - 1] = '(' then
          s[i - 1] := ')';
        if level = max then
          level -= 1;
      end;
    end;
    levels.Add(maxlevel);
    levels.Add(max);
  end;
  levels.Reverse;
  for var i := 0 to s.Length - 1 do
    if s[i] = '(' then
      s[i] := ')';
  Write(levels);
  Result := res;
end;


