function MakePalindrome(str: string): string;
begin
  var n := str.Length;
  var rev_str := str.ReverseString;
  var (i, j) := (0, 0);
  while j < n do
  begin
    if str[i] <> str[j] then
      break;
    Inc(i);
    Inc(j);
  end;
  if i < n then
    str := str.Substring(0, j) + rev_str.Substring(0, n - j) + str.Substring(i);
  Result := str;
end;

function MakePalindrome2(s: string): string;
{ Find the shortest palindrome that begins with a supplied string.
    Algorithm idea is simple:
    - Find the longest postfix of supplied string that is a palindrome.
    - Append to the end of the string reverse of a string prefix that comes before the palindromic suffix.
    >>> MakePalindrome('')
    ''
    >>> MakePalindrome('cat')
    'catac'
    >>> MakePalindrome('cata')
    'catac' }
begin
  var n := s.Length;
  var (i, j) := (0, 0);
  while j < n do
  begin
    if s[i] <> s[n - j - 1] then
      break;
    i += 1;
    j += 1;
  end;
  if i < n then
    s := s.Substring(0, j) + s.ReverseString.Substring(0, n - j) + s.Substring(i);
  Result := s;
end;


