function HowManyTimes(str: string; substring: string): integer;
begin
  var n := str.Length;
  var m := substring.Length;
  var res := 0;
  var border := 0;
  var bw := new byte[m];
  for var i := 0 to m - 1 do
    bw[i] := byte(substring[i]);
  var f := new boolean[m];
  for var i := 0 to m - 1 do
    f[i] := str.Contains(substring[i]);
  for var i := 0 to n - m + border - 1 do
  begin
    var flag := true;
    for var j := 0 to m - 1 do
      if (i + j >= n) or (f[j] and (str[i + j] <> substring[j])) then
      begin
        flag := false;
        break;
      end;
    if flag then
      Inc(res);
  end;
  Result := res;
end;


