function RescaleToUnit(numbers : array of real): array of real; 
begin
  var min := numbers.Min;
  var max := numbers.Max;
  for var i := 0 to numbers.Length - 1 do
    numbers[i] := (numbers[i] - min) / (max - min);
  var sum := numbers.Sum;
  for var i := 0 to numbers.Length - 1 do
    numbers[i] /= sum;
  Result := numbers;
end;


