function RemoveDuplicates(numbers: array of integer): array of integer;
begin
  var d := new Dictionary<integer, integer>;
  Result := new integer[numbers.Length];
  var n := 0;
  foreach var x in numbers do
  begin
    if d.ContainsKey(x) and d[x] = 0 then
    begin
      d[x] := 1;
      Result[n] := x;
      n += 1;
    end
    else if not d.ContainsKey(x) then
    begin
      d[x] := 0;
      Result[n] := x;
      n += 1;
    end
  end;
end;


