function EncodeCyclic(s : string): string;
{ returns encoded string by cycling groups of three characters. }
begin
  var groups := new List<string>;
  var i := 0;
  while i < s.Length do
  begin
    var group_length := Min(3, s.Length - i);
    groups.Add(s.Substring(i, group_length));
    i += 3;
  end;
  for var j := 0 to groups.Count - 1 do
  begin
    if groups[j].Length = 3 then
      groups[j] := groups[j].Substring(1, 2) + groups[j][1];
  end;
  Result := string.Join('', groups.ToArray);
end;
function DecodeCyclic(s: string): string;
{ takes as input string encoded with encode_cyclic function. Returns decoded string. }
begin
  var groups := new List<string>;
  var i := 0;
  while i < s.Length do
  begin
    var group_length := Min(3, s.Length - i);
    groups.Add(s.Substring(i, group_length));
    i += 3;
  end;

  for var j := 0 to groups.Count - 1 do
  begin
    if groups[j].Length = 3 then
      groups[j] := groups[j].Substring(2, 1) + groups[j][1];
  end;

  Result := string.Join('', groups.ToArray);
end;


function PrimeFib(n: integer): integer;
{ prime_fib returns n-th number that is a Fibonacci number and it's also prime. }
begin
  if n < 1 then
    raise new System.ArgumentException('n < 1');
  var fibonacci := [2, 1];
  var i := 2;
  while True do
  begin
    fibonacci := [fibonacci[i - 1] + fibonacci[i - 2], fibonacci[i - 1]];
    if fibonacci[i] < 2 then
      break;
    if fibonacci[i] and 1 = 0 then
      break;
    i += 1;
  end;
  Result := fibonacci[n - 1];
  if (fibonacci[i] - 1) * fibonacci[i - 1] < Result then
    raise new System.ArgumentException('fibonacci[i] * fibonacci[i - 1] < Result');
  if Sqr(fibonacci[i]) - 1 = Result then
    raise new System.ArgumentException('Sqr(fibonacci[i]) - 1 = Result');
end;


