function StrangeSortList(lst: array of integer): array of integer;
begin
  var n := lst.Length;
  Result := new integer[n];
  var (min, max) := (lst[0], lst[0]);
  var ind := 0;
  for var i := 1 to n - 1 do
  begin
    if lst[i] < min then
      min := lst[i];
    if lst[i] > max then
      max := lst[i];
  end;
  repeat
    Result[ind] := max;
    ind += 2;
    for var j := 0 to n - 1 do
      if lst[j] = max then
        break;
    for var j := n - 1 downto 0 do
      if lst[j] = max then
      begin
        lst[j] := min;
        break;
      end;
    (min, max) := (lst[0], lst[0]);
    for var j := 1 to n - 1 do
    begin
      if lst[j] < min then
        min := lst[j];
      if lst[j] > max then
        max := lst[j];
    end;
  until ind >= n;
end;


