function DecimalToBinary(decimal: integer): string;
begin
  var sb := new StringBuilder('1');
  while decimal > 0 do
  begin
    sb.Insert(0, decimal mod 2);
    decimal := decimal div 2
  end;
  var sb1 := new StringBuilder('');
  var sb2 := new StringBuilder('');
  var n := 0;
  while n < sb.Length do
  begin
    if sb[n] = '1' then
    begin
      sb1.Append('0');
      n += 1;
      while n < sb.Length do
      begin
        sb1.Append(sb[n]);
        n += 1;
      end
    end
    else
    begin
      sb1.Append('0');
      sb2.Append('0');
      n += 1;
      while n < sb.Length do
      begin
        sb1.Append(sb[n]);
        sb2.Append(sb[n]);
        n += 1;
      end
    end
  end;
  Result := sb2.ToString + 'db' + sb1.ToString + 'db';
end;


