function Bin(N: integer): string;
begin
  if N < 0 then
    N := -N;
  var q := &1;
  var s := 0;
  while q <= N do
  begin
    if N >= q then
    begin
      N -= q;
      s += 1;
    end;
    q *= 2;
  end;
  var r := &1;
  var b := new char[s];
  var i := s - 1;
  while r <= N do
  begin
    if N >= r then
    begin
      N -= r;
      b[i] := '1';
      i -= 1;
    end
    else b[i] := '0';
    r *= 2;
  end;
  Result := b.JoinToString('');
end;


