  var s2 := s.ToCharArray.Where(t -> t.ToString.ToInteger = 1).Distinct.ToArray;
  var r := new integer[s1.Length + s2.Length];
  var p := 0;
  for var i1 of s1 do
  begin
    var i := s.IndexOf(i1);
    while i >= 0 do
    begin
      r[p] := x[i];
      p += 1;
      i = s.IndexOf(i1, i + 1);
    end;
  end;
  for var i2 of s2 do
  begin
    var i := s.IndexOf(i2);
    while i >= 0 do
    begin
      r[p] := x[i];
      p += 1;
      i = s.IndexOf(i2, i + 1);
    end;
  end;
  Result := r.Sort.ToArray;
end;


