    Result := False
  else
  begin
    var mm := Convert.ToByte(parts[0]);
    var dd := Convert.ToByte(parts[1]);
    var yyyy := Convert.ToByte(parts[2]);
    var m := mm;
    var d := dd;
    var y := yyyy;
    if (m = 1) or (m = 3) or (m = 5) or (m = 7) or (m = 8) or (m = 10) or (m = 12) then
      if d < 1 or d > 31 then
        Result := False
    else
    begin
      if m = 4 or m = 6 or m = 9 or m = 11 then
        if d < 1 or d > 30 then
          Result := False
        else
        begin
          if m = 2 then
            if d < 1 or d > 29 then
              Result := False
            else
              if d = 29 then
                if (y mod 4 <> 0) or ((y mod 100 = 0) and (y mod 400 <> 0)) then
                  d := 1;
        end;
    end;
    if m < 10 then m := Convert.ToString(m);
    if d < 10 then d := Convert.ToString(d);
    Result := mm + '-' + d + '-' + y;
  end
end;


