function Minpath(grid: array of array of integer; k: integer): array of integer;
begin
  var n := grid.Length;
  var res := ArrFill(k, 0);
  var used := ArrFill(n * n, false);
  var Neighbors := [[0, 1], [0, -1], [1, 0], [-1, 0]];
  var min := integer.MaxValue;
  var cur := ArrFill(k, 0);
  var path := ArrFill(k, 0);
  var q := [[0, cur, []]];
  while q.Count > 0 do
  begin
    var ind := q[0][0];
    cur.CopyTo(tmp, 0);
    if tmp.Min(k - 1) < min then
    begin
      min := tmp.Min(k - 1);
      path.CopyTo(res, ind + 1);
    end;
    q.RemoveAt(0);
    var x := q.Count;
    if ind = x then
      break;
    for var j := 0 to Neighbors.Length - 1 do
    begin
      var dx := q[0][0] + 1;
      var nx := tmp[j];
      tmp[j] := cur[j];
      if (nx < k) and (grid[tmp[j] div n * n][tmp[j] mod n] = grid[tmp[dx] div n * n][tmp[dx] mod n] + 1) and not used[nx] then
      begin
        q.Add([dx, tmp, Neighbors[j]]);
        used[nx] := true;
      end;
      tmp[j] := cur[j];
    end;
  end;
  Result := res;
end;


