function IsNested(s: string): boolean;
begin
  var q := new Queue<char>(s);
  var stack := new Stack<char>;
  while q.Count > 0 do
  begin
    var cur := q.Dequeue;
    if cur = '[' then
      stack.Push(cur)
    else if stack.Count > 0 then
    begin
      stack.Pop();
      if stack.Count = 0 then
        return True;
    end
    else if cur <> ']' then
      q.Enqueue(cur);
  end;
  Result := stack.Count = 0;
end;


