  for var i := n - 2 downto 0 do
    if arr[i] > arr[i + 1] then
    begin
      var j := i;
      while (j >= 0) and (arr[j] > arr[i]) do
        j := arr.BinarySearch(arr[j] - 1, j + 1);
      if j >= 0 then
        arr[j] -= 1;
      arr[i + 1] := arr[i] - 1;
      Result := i
      exit;
    end;
  Result := -1;
end;


