    var nb := b.Sum(x -> x);
    if na = nb then
      a.Zip(b,(x,y)->x-y).Sum(t->t)
    else na - nb;
  });
end;


function Specialfilter(nums: array of integer): integer;
begin
  Result := 0;
  foreach var num in nums do
  begin
    var dig := Abs(num);
    var first := dig mod 10;
    var last := dig div 10 mod 10;
    if (num > 10) and (first <> 0) and (first mod 2 = 1) and (last <> 0) and (last mod 2 = 1) then
      Result += 1;
  end;
end;


function GetMaxTriples(n: integer): integer;
begin
  var a := new integer[n];
  for var i := 0 to n - 1 do
    a[i] := i * i - i + 1;
  Result := 0;
  for var i := 0 to n - 1 do
    for var j := i + 1 to n - 1 do
      for var k := j + 1 to n - 1 do
        if (a[i] + a[j] + a[k]) mod 3 = 0 then
          Result += 1;
end;


