function Compare(game, guess : array of integer): array of integer;
begin
  Result := new integer[guess.Length];
  for var i := 0 to guess.Length - 1 do
    Result[i] := guess[i] - game[i];
  Result.Select(var x -> x = -1 or x = 1 ? abs(x) : 0);
end;


function StrongestExtension(className: string; extensions: array of string): string;
begin
  var max := -1.0;
  var strongestExtension := '';
  foreach var ext in extensions do
  begin
    var cap := ext.Count(char -> char.IsUpper);
    var sm := ext.Count(char -> char.IsLower);
    var strength := cap - sm;
    if strength > max then
    begin
      max := strength;
      strongestExtension := ext;
    end;
  end;
  Result := className + '.' + strongestExtension;
end;


function CycpatternCheck(a, b: string): boolean;
