function EvenOddCount(num : integer): (integer, integer);
begin
  var even := 0;
  var odd := 0;
  var absnum := Abs(num);
  while absnum >= 10 do
  begin
    var digit := absnum mod 10;
    if digit mod 2 = 0 then
      even += 1
    else
      odd += 1;
    absnum := absnum div 10
  end;
  if num < 0 then
    Result := (odd, even)
  else Result := (even, odd)
end;


function IntToMiniRoman(number: integer): string;
  begin
    var roman := '';
    var ar := [500, 100, 90, 40, 10, 9, 4, 1];
    var br := ['d', 'c', 'xc', 'l', 'x', 'v', 'i', 'ii'];
    for var i := 0 to ar.Length - 1 do
    begin
      var cnt := number div ar[i];
      number := number mod ar[i];
      while cnt > 0 do
      begin
        roman += br[i];
        cnt -= 1;
      end;
    end;
    Result := roman;
  end;
end.


