function Solve(s: string): string;
begin
  var sb := new StringBuilder;
  var char_found := false;
  foreach var c in s do
  begin
    if char.IsLetter(c) then
    begin
      char_found := true;
      if char.IsUpper(c) then
        sb.Append(char.ToLower(c))
      else sb.Append(char.ToUpper(c))
    end
    else
    begin
      char_found := false;
      if c = ' ' then
        sb.Append(c)
      else if c = '.' then
        if sb.Length > 0 then sb.Append(c)
    end;
  end;
  if not char_found and sb.Length > 0 then
    sb.Reverse
  else
  begin
    var char_array := s.ToCharArray;
    Array.Reverse(char_array);
    sb.Append(new string(char_array));
  end;
  Result := sb.ToString
end;


function StringToMd5(text: string): string;
begin
  if text = '' then
    Result := ''
  else
    Result := Encoding.ASCII.GetBytes(text).MD5.ToByteArray.Select(t -> t.ToString('x2')).JoinToString('');
end;


function GenerateIntegers(a, b: integer): array of integer;
begin
  if a > b then
    Swap(a, b);
  Result := new integer[a - b + 1];
  var i := 0;
  for var x := a - 1 downto b + 1 do
  begin
    if (x mod 2 = 0) and (x >= 0) then
    begin
      Result[i] := x;
      i += 1;
    end;
  end;
end;
